-- Current finite metadata evidence and explicit lineage. No historical conversion.
ALTER TABLE provider_attempts ADD COLUMN delivery_id INTEGER REFERENCES metadata_deliveries(id);
ALTER TABLE recording_identifiers ADD COLUMN delivery_id INTEGER REFERENCES metadata_deliveries(id);
ALTER TABLE recording_identifiers ADD COLUMN observation_id INTEGER REFERENCES metadata_observations(id);
CREATE TABLE metadata_legacy_records (legacy_owner TEXT NOT NULL CHECK(legacy_owner IN ('metadata_findings','enrichment_log','metadata_decisions','entry_field_choices','enrichment_conflict','recording_identifiers','provider_attempts','enrichment_provider_state','catalog_field_hints')),legacy_id INTEGER NOT NULL CHECK(typeof(legacy_id)='integer'),delivery_id INTEGER NOT NULL REFERENCES metadata_deliveries(id),entry_id INTEGER REFERENCES catalog_entries(id),recording_id INTEGER REFERENCES recordings(id),input_video_id TEXT REFERENCES youtube_items(video_id),disposition TEXT NOT NULL CHECK(disposition IN ('catalog_evidence','native_observation','unsupported_field','invalid_value','unproven_subject','unproven_scope','operational_state')),PRIMARY KEY(legacy_owner,legacy_id)) WITHOUT ROWID;
CREATE INDEX ix_metadata_legacy_delivery ON metadata_legacy_records(delivery_id);
CREATE TRIGGER owned_metadata_legacy_record BEFORE INSERT ON metadata_legacy_records WHEN NOT EXISTS(SELECT 1 FROM metadata_deliveries d WHERE d.id=NEW.delivery_id AND d.key_contract='legacy_record' AND d.raw_filename IS NOT NULL) BEGIN SELECT RAISE(ABORT,'Legacy metadata requires its retained original delivery'); END;
CREATE TRIGGER immutable_metadata_legacy_record BEFORE UPDATE ON metadata_legacy_records BEGIN SELECT RAISE(ABORT,'Legacy metadata capture is immutable'); END;
CREATE TRIGGER retained_metadata_legacy_record BEFORE DELETE ON metadata_legacy_records BEGIN SELECT RAISE(ABORT,'Legacy metadata capture requires a retention disposition'); END;
CREATE TABLE native_metadata_observations (id INTEGER PRIMARY KEY AUTOINCREMENT,delivery_id INTEGER NOT NULL REFERENCES metadata_deliveries(id),position INTEGER NOT NULL CHECK(typeof(position)='integer' AND position>=0),field TEXT NOT NULL CHECK(field IN ('tags','bpm','energy','danceability','mood_party','mood_aggressive','music_key','music_scale','mood_happy','mood_sad','mood_relaxed','mood_acoustic','instrumental','loudness','dynamic_complexity')),kind TEXT NOT NULL CHECK(kind IN ('reported','measurement','prediction','curated','inherited','derived')),unit TEXT CHECK(unit IS NULL OR (typeof(unit)='text' AND length(CAST(unit AS BLOB)) BETWEEN 1 AND 256)),legacy_finding_id INTEGER UNIQUE,UNIQUE(delivery_id,position));
CREATE TRIGGER owned_native_metadata_delivery BEFORE INSERT ON native_metadata_observations WHEN NEW.legacy_finding_id IS NULL AND NOT EXISTS(SELECT 1 FROM metadata_deliveries d WHERE d.id=NEW.delivery_id AND d.key_contract IN ('capture','provider_revision') AND d.input_entry_id IS NOT NULL AND d.input_recording_id IS NOT NULL AND d.provider_entity_type IN ('recording','release','artist','genre','item')) BEGIN SELECT RAISE(ABORT,'Native metadata requires its captured source and input'); END;
CREATE TRIGGER owned_native_metadata_legacy BEFORE INSERT ON native_metadata_observations WHEN NEW.legacy_finding_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM metadata_legacy_records r WHERE r.legacy_owner='metadata_findings' AND r.legacy_id=NEW.legacy_finding_id AND r.delivery_id=NEW.delivery_id) BEGIN SELECT RAISE(ABORT,'Native metadata requires its retained original'); END;
CREATE TRIGGER immutable_native_metadata_observation BEFORE UPDATE ON native_metadata_observations BEGIN SELECT RAISE(ABORT,'Native metadata evidence is immutable'); END;
CREATE TABLE musical_source_observations (source_key TEXT NOT NULL REFERENCES rec_musical_sources(source_key),field TEXT NOT NULL CHECK(field IN ('tags','bpm','energy','danceability','mood_party','mood_aggressive','music_key','music_scale','mood_happy','mood_sad','mood_relaxed','mood_acoustic','instrumental','loudness','dynamic_complexity')),observation_id INTEGER NOT NULL REFERENCES native_metadata_observations(id),PRIMARY KEY(source_key,field)) WITHOUT ROWID;
CREATE INDEX ix_musical_source_observation ON musical_source_observations(observation_id);
CREATE TRIGGER owned_musical_source_observation_insert BEFORE INSERT ON musical_source_observations WHEN NOT EXISTS(SELECT 1 FROM native_metadata_observations o JOIN metadata_deliveries d ON d.id=o.delivery_id JOIN rec_musical_sources s ON s.source_key=NEW.source_key WHERE o.id=NEW.observation_id AND o.field=NEW.field AND s.provider=d.provider AND s.scope=d.provider_entity_type AND s.entity_id=d.provider_entity_id) BEGIN SELECT RAISE(ABORT,'Musical source selection has a different provider entity or field'); END;
CREATE TRIGGER owned_musical_source_observation_update BEFORE UPDATE ON musical_source_observations WHEN NOT EXISTS(SELECT 1 FROM native_metadata_observations o JOIN metadata_deliveries d ON d.id=o.delivery_id JOIN rec_musical_sources s ON s.source_key=NEW.source_key WHERE o.id=NEW.observation_id AND o.field=NEW.field AND s.provider=d.provider AND s.scope=d.provider_entity_type AND s.entity_id=d.provider_entity_id) BEGIN SELECT RAISE(ABORT,'Musical source selection has a different provider entity or field'); END;
CREATE TABLE metadata_observations (id INTEGER PRIMARY KEY AUTOINCREMENT,delivery_id INTEGER REFERENCES metadata_deliveries(id),entry_id INTEGER REFERENCES catalog_entries(id),recording_id INTEGER REFERENCES recordings(id),input_video_id TEXT REFERENCES youtube_items(video_id),field_scope TEXT NOT NULL CHECK(field_scope IN ('recording','release','item','legacy_item','legacy_recording')),field TEXT NOT NULL CHECK(field IN ('genre','bpm','energy','danceability','mb_recording_id','music_key','music_scale','mood_happy','mood_sad','mood_relaxed','mood_acoustic','instrumental','title','artist','orig_title','orig_artist','album','duration_s','available','video_type','artist_browse_id','album_browse_id','thumbnail','mb_year','loudness','dynamic_complexity','popularity','gain','label')),value_kind TEXT NOT NULL CHECK(value_kind IN ('value','null','blank','unresolved','withdrawn')),text_value TEXT CHECK(text_value IS NULL OR length(CAST(text_value AS BLOB))<=65536),number_value CHECK(number_value IS NULL OR (typeof(number_value) IN ('integer','real') AND number_value BETWEEN -1.7976931348623157e308 AND 1.7976931348623157e308)),genre_key TEXT REFERENCES genre_catalog(key),unit TEXT,resolution_reason TEXT CHECK(resolution_reason IS NULL OR length(resolution_reason)>0),observed_at REAL CHECK(observed_at IS NULL OR (typeof(observed_at) IN ('integer','real') AND observed_at BETWEEN -1.7976931348623157e308 AND 1.7976931348623157e308)),origin TEXT NOT NULL CHECK(origin IN ('provider','user','legacy_finding','legacy_log','legacy_choice','legacy_conflict','legacy_attempt','legacy_state','legacy_hint','selection_snapshot','selection_transfer')),legacy_source TEXT,source_run_id TEXT CHECK(source_run_id IS NULL OR length(CAST(source_run_id AS BLOB))<=4096),legacy_reference TEXT CHECK(legacy_reference IS NULL OR length(CAST(legacy_reference AS BLOB))<=4096),legacy_owner TEXT CHECK(legacy_owner IS NULL OR legacy_owner IN ('metadata_findings','enrichment_log','metadata_decisions','entry_field_choices','enrichment_conflict','recording_identifiers','provider_attempts','enrichment_provider_state','catalog_field_hints')),legacy_id INTEGER,legacy_position INTEGER NOT NULL DEFAULT 0 CHECK(typeof(legacy_position)='integer' AND legacy_position>=0),derived_from_observation_id INTEGER REFERENCES metadata_observations(id),FOREIGN KEY(legacy_owner,legacy_id) REFERENCES metadata_legacy_records(legacy_owner,legacy_id),CHECK((origin='provider' AND delivery_id IS NOT NULL AND legacy_source IS NULL) OR origin<>'provider'),CHECK(observed_at IS NOT NULL OR origin LIKE 'legacy_%' OR origin='selection_snapshot'),CHECK((origin='selection_transfer')=(derived_from_observation_id IS NOT NULL)),CHECK((legacy_owner IS NULL AND legacy_id IS NULL) OR (legacy_owner IS NOT NULL AND legacy_id IS NOT NULL)), CHECK(field_scope NOT IN ('legacy_item','legacy_recording') OR (origin LIKE 'legacy_%' AND legacy_owner IS NOT NULL)),CHECK(entry_id IS NOT NULL OR (field_scope='legacy_recording' AND origin IN ('legacy_attempt','legacy_state'))),CHECK(field_scope<>'legacy_recording' OR (entry_id IS NULL AND recording_id IS NOT NULL)),CHECK(recording_id IS NOT NULL OR field_scope='legacy_item'),CHECK((field IN ('mb_year','label') AND field_scope='release') OR (field IN ('genre','bpm','energy','danceability','mb_recording_id','music_key','music_scale','mood_happy','mood_sad','mood_relaxed','mood_acoustic','instrumental') AND field_scope='recording') OR (field IN ('title','artist','orig_title','orig_artist','album','duration_s','available','video_type','artist_browse_id','album_browse_id','thumbnail','loudness','dynamic_complexity','popularity','gain') AND field_scope='item') OR (field IN ('loudness','dynamic_complexity') AND field_scope='recording') OR field_scope IN ('legacy_item','legacy_recording')),CHECK((value_kind='null' AND text_value IS NULL AND number_value IS NULL AND genre_key IS NULL AND unit IS NULL AND resolution_reason IS NULL) OR (value_kind='blank' AND text_value IS NOT NULL AND text_value='' AND number_value IS NULL AND genre_key IS NULL AND unit IS NULL AND resolution_reason IS NULL) OR (value_kind='withdrawn' AND origin IN ('user','legacy_choice') AND delivery_id IS NULL AND text_value IS NULL AND number_value IS NULL AND genre_key IS NULL AND unit IS NULL AND resolution_reason IS NULL) OR (value_kind='unresolved' AND legacy_owner IS NOT NULL AND delivery_id IS NOT NULL AND text_value IS NULL AND number_value IS NULL AND genre_key IS NULL AND unit IS NULL AND resolution_reason IS NOT NULL) OR (value_kind='value' AND ((field IN ('genre','mb_recording_id','music_key','music_scale','title','artist','orig_title','orig_artist','album','video_type','artist_browse_id','album_browse_id','thumbnail','mb_year','label') AND text_value IS NOT NULL AND length(text_value)>0 AND number_value IS NULL AND unit IS NULL AND ((field='genre' AND ((genre_key IS NOT NULL AND resolution_reason IS NULL) OR (genre_key IS NULL AND resolution_reason IS NOT NULL AND resolution_reason IN ('unknown_genre','ambiguous_genre')))) OR (field<>'genre' AND genre_key IS NULL AND resolution_reason IS NULL))) OR (number_value IS NOT NULL AND text_value IS NULL AND genre_key IS NULL AND resolution_reason IS NULL AND unit IS NOT NULL AND ((field='bpm' AND unit='bpm' AND number_value>0) OR (field='duration_s' AND unit='seconds' AND typeof(number_value)='integer' AND number_value>=0) OR (field='available' AND unit='boolean' AND typeof(number_value)='integer' AND number_value IN (0,1)) OR (field='popularity' AND unit='provider_score' AND typeof(number_value)='integer') OR (field='gain' AND unit='decibels') OR (field='loudness' AND unit='essentia.average_loudness') OR (field='dynamic_complexity' AND unit='essentia.dynamic_complexity') OR (field='energy' AND unit IN ('legacy_energy_0_1','fraction') AND number_value BETWEEN 0 AND 1) OR (field IN ('danceability','mood_happy','mood_sad','mood_relaxed','mood_acoustic','instrumental') AND unit IN ('classifier_probability','fraction') AND nu